def index(rows: list[tuple[str, str]]) -> str:
    out = ["# خريطةُ الجلسات الثابتة: من يفعل ماذا", "", "> مولَّدةٌ من `tabs.json`. كلُّ جلسةٍ تقرأ بطاقتَها `role_cards/<رقمها>.md` عند البدء، وتعرف بهذه الخريطة مَن تخاطب.", "",
           "| الجلسة | دورُها في سطر | بطاقتُها |", "|---|---|---|"]
    out += [f"| {t} | {r} | `role_cards/{t.split(' · ')[0]}.md` |" for t, r in rows]
    out += ["", "- **الجلساتُ المرنة (04SS):** بطاقتُها المشتركة `role_cards/04.md` (تسلسلُ العمل: أودِع ← «جاهزٌ للمعاينة» لـ0501 ← تحقّق بـapproval_check ← ادفع ← سلّم؛ ولا تسأل المالك).", "", "## إلى مَن أذهب؟",
            "- مهمّةٌ جديدة أو اكتشافٌ أثناء العمل ← **0201** (بطاقة بزمنٍ وأولويّة) ثمّ 0301 تصنّف وتسمّي.",
            "- توجيهٌ وأولويّاتٌ وأزمات ← **0101**. وخللٌ في المنظومة أو الفلو أو السجلّ ← **0102**.",
            "- جاهزٌ للمعاينة واعتمادُ المالك ← **0501**. دمجٌ ونشرٌ وطلباتُ الدمج ← **0601**.",
            "- حكمٌ على تنبيهٍ أمنيٍّ أو ثغرة ← **0104** (0701 ترصد وتحيل). امتثالٌ وقانونٌ وقواعدٌ ← **0103**.",
            "- خيارات مقيسةٌ لقرارٍ مفتوحٌ ← **0102**. مرجعٌ وزاريٌّ وتصنيفٌ وتسمية ← **0301**.",
            "- خارطةٌ بعد الدمج وقياسُ جودةٍ بعد النشر ورصدٌ وأتمتةُ مهمّةٍ دوريّةٍ في الكود ← **0701**.", ""]
    return "\n".join(out)


def main() -> int:
    sys.stdout.reconfigure(encoding="utf-8")
    project = sys.argv[1] if len(sys.argv) > 1 else "schoolos"
    tabs = json.loads((ROOT / "projects" / project / "tabs.json").read_text(encoding="utf-8"))
    by_number = {t.get("number"): t for t in tabs["tabs"]}
    global COMMON
    COMMON = COMMON + "\n" + common_tools(tabs)
    outdir = ROOT / "role_cards"
    outdir.mkdir(exist_ok=True)
    rows = []
    details = outdir / "details"
    details.mkdir(exist_ok=True)
    (outdir / "COMMON.md").write_text(COMMON, encoding="utf-8")
    for title, ch in sorted(tabs["session_policy"]["charters"].items()):
        sid = title.split(" · ")[0]
        full = card(title, ch, by_number.get(sid[:2]))
        if sid in NUCLEUS_ROLES:
            (details / f"{sid}.md").write_text(full, encoding="utf-8")
            full = nucleus(title, ch, by_number.get(sid[:2]))
        (outdir / f"{sid}.md").write_text(full, encoding="utf-8")
        rows.append((title, ch["role"].split("؛")[0].split("。")[0][:140]))
    for tab in tabs["tabs"]:
        if tab.get("id") == "execute":
            full = flexible_card(tab)
            if "04" in NUCLEUS_ROLES:
                (details / "04.md").write_text(full, encoding="utf-8")
                full = nucleus_flexible(tab)
            (outdir / "04.md").write_text(full, encoding="utf-8")
    (outdir / "INDEX.md").write_text(index(rows), encoding="utf-8")
    print(f"role_cards/ ✔ ({len(rows)} بطاقة + INDEX)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
